import json, glob, os, re, sys
D='/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/subagents/workflows/wf_d5ec6194-bcc/'
labels={}
for l in open(D+'journal.jsonl'):
    d=json.loads(l)
    if d.get('type')=='started': labels[d['agentId']]=d['label']
out=open('cmds.tsv','w')
res=open('results.jsonl','w')
for f in sorted(glob.glob(D+'agent-*.jsonl')):
    aid=os.path.basename(f)[6:-6]; lab=labels.get(aid,'?')
    pending={}
    for line in open(f):
        try: d=json.loads(line)
        except: continue
        t=d.get('timestamp','')
        m=d.get('message',{})
        c=m.get('content')
        if d.get('type')=='assistant' and isinstance(c,list):
            for b in c:
                if b.get('type')=='tool_use':
                    inp=b.get('input',{})
                    cmd=inp.get('command') or inp.get('file_path') or json.dumps(inp)[:300]
                    pending[b['id']]=(t,b.get('name'),cmd)
                    out.write(f"{lab}\t{t[11:19]}\t{b.get('name')}\t{json.dumps(cmd)[:600]}\n")
        if d.get('type')=='user' and isinstance(c,list):
            for b in c:
                if b.get('type')=='tool_result':
                    tid=b.get('tool_use_id'); cc=b.get('content')
                    if isinstance(cc,list): cc=''.join(x.get('text','') for x in cc if isinstance(x,dict))
                    p=pending.get(tid)
                    if p: res.write(json.dumps(dict(label=lab,t=p[0],rt=t,name=p[1],cmd=p[2],len=len(cc or ''),res=(cc or '')[:3000],tail=(cc or '')[-1500:]))+'\n')
EOF
python3 cmds.py; wc -l cmds.tsv; grep -cE 'compileAll' cmds.tsv; grep -E 'compileAll|testSystem|testFast|run_in_background' cmds.tsv | cut -c1-300 | head -80

